// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { addProductToCart } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/logout`);
    await page.goto(`${baseUrl}/product/1YMWWN1N4O`);
    await addProductToCart(page, "3");
    await expect(page).toHaveURL(`${baseUrl}/cart`);
    await expect(page.locator('#cart-count-badge')).toHaveText('3');

    // Navigate to the home page, which is served by a different handler that must
    // inject cart_size independently for the header badge to survive the transition.
    await page.getByRole("link").nth(0).click();
    await page.waitForLoadState('networkidle');
    await expect(page).toHaveURL(`${baseUrl}/`);
    await expect(page.getByRole('heading', { name: 'Hot Products' })).toBeVisible();
    await expect(page.locator('#cart-count-badge')).toHaveText('3');
    await expect(page.getByRole("link", { name: "Cart icon" })).toContainText("3");
});
